import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.DTdEDYjJ.js";const k=JSON.parse('{"title":"接入 Bot 与发布连接器","description":"","frontmatter":{},"headers":[],"relativePath":"development/integrate-and-publish.md","filePath":"development/integrate-and-publish.md"}'),i={name:"development/integrate-and-publish.md"};function o(r,e,l,p,h,d){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="接入-bot-与发布连接器" tabindex="-1">接入 Bot 与发布连接器 <a class="header-anchor" href="#接入-bot-与发布连接器" aria-label="Permalink to &quot;接入 Bot 与发布连接器&quot;">​</a></h1><p>开发者可以把自己的应用暴露为 MCP 服务，再用开源的 AgentApp Connector 生成各客户端所需的配置和市场提交材料。它从 Bot Studio 的单 Bot 发布场景出发，支持 WorkBuddy、千问办公、豆包工作、ChatGPT / Codex、Cursor、Claude 和 ZCode。公开源码为 0.0.4，市场材料均处于 <code>NOT-SUBMITTED</code>。 <a href="https://github.com/Harzva/agentapp-connector" target="_blank" rel="noreferrer">AgentApp Connector</a></p><h2 id="把自己的应用接入-agent-平台" tabindex="-1">把自己的应用接入 Agent 平台 <a class="header-anchor" href="#把自己的应用接入-agent-平台" aria-label="Permalink to &quot;把自己的应用接入 Agent 平台&quot;">​</a></h2><ol><li><p><strong>准备 MCP 服务。</strong> 已有 MCP 的应用可以用自己的 HTTPS 端点或可执行的 stdio 入口。只有 REST / OpenAPI 的应用，先实现一层 MCP 服务，把选定的业务操作映射成命名清楚的工具，并为工具声明参数、结果、读写副作用和授权范围。AgentApp Connector 的输入是 MCP URL 或 stdio 路径，OpenAPI 到 MCP 的映射由应用开发者实现。</p></li><li><p><strong>生成客户端配置。</strong> 在 Node.js 18 或更新版本下克隆仓库。将示例地址替换成自己的 MCP 地址，按客户端输出的 JSON、TOML 或表单指引配置。远程地址须使用 HTTPS，回环 HTTP 可用于本机开发。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Harzva/agentapp-connector.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agentapp-connector</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/cli.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> targets</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/cli.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://mcp.example.invalid/mcp&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workbuddy-http</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/cli.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> guide</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://mcp.example.invalid/mcp&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doubao-work</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/cli.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://mcp.example.invalid/mcp&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> placeholder</span></span></code></pre></div><p>如果客户端走 stdio，用 <code>--connector-path</code> 指定你自己可执行的 MCP 启动脚本。例如 <code>node src/cli.mjs config --target claude-desktop --connector-path /path/to/mcp-launcher</code>。0.0.4 仍沿用 <code>openbot</code> 配置键和示例工具，支持自定义端点和入口路径。发布自己的应用时，再替换包名、市场键、工具说明以及图标。通用应用档案还未成为 CLI 输入。</p></li><li><p><strong>在目标客户端验证。</strong> 完成客户端的信任或授权流程后，验证 MCP 初始化、工具枚举、一次允许的业务调用，以及一次应被拒绝的调用。配置生成只写标准输出，示例授权字段只含占位符。实际凭据通过客户端为调用方单独配置。 <a href="https://github.com/Harzva/agentapp-connector/blob/main/docs/LOCAL-MODES.md" target="_blank" rel="noreferrer">各客户端本地模式</a></p></li></ol><h2 id="生成市场材料并提交" tabindex="-1">生成市场材料并提交 <a class="header-anchor" href="#生成市场材料并提交" aria-label="Permalink to &quot;生成市场材料并提交&quot;">​</a></h2><p>在 AgentApp Connector 的检出目录运行以下命令。第一条重生成 <code>marketplace/</code> 的材料，第二条显示各平台的审核路径和前置项，也可加 <code>--platform workbuddy</code> 针对单个平台查看。预检对应仓库内的发布样例，开发者需要用自己端点的验收结果逐条核对。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/cli.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> market-preflight</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> text</span></span></code></pre></div><p>各平台目录有 <code>SUBMISSION.md</code>。其中部分目录附清单、配置或请求体占位文件。用应用自己的名称、版本、图标、权限说明、隐私政策与可复现测试说明补齐材料。需要远程调用的平台还需验证服务器可达性和认证。保留提交回执，审核通过后再记录实际公开链接。 <a href="https://github.com/Harzva/agentapp-connector/tree/main/marketplace" target="_blank" rel="noreferrer">市场材料目录</a> · <a href="https://github.com/Harzva/agentapp-connector/blob/main/marketplace/SUBMIT-STEPS.md" target="_blank" rel="noreferrer">预检步骤</a></p><table tabindex="0"><thead><tr><th>目标</th><th>本地配置与提交路径</th></tr></thead><tbody><tr><td>WorkBuddy</td><td>生成 MCP 配置。市场包按 MCP + Skill 路径准备 <code>connector-meta.json</code>、<code>mcp.json</code>、图标和技能材料，完成主体认证后提交审核。 <a href="https://open.workbuddy.cn/docs/connector" target="_blank" rel="noreferrer">连接器规范</a></td></tr><tr><td>千问办公 QwenWork</td><td>生成 MCP 配置。仓库提供组织内提交清单和 OpenAPI 请求体占位，按组织权限与审核流程发布。 <a href="https://help.aliyun.com/zh/qwenwork/connector-management" target="_blank" rel="noreferrer">连接器管理</a></td></tr><tr><td>豆包工作</td><td>生成自定义连接器填表指引和入驻清单。平台接入规范以入驻后的后台为准，当前仓库未提供可提交包。 <a href="https://open.doubao.com/" target="_blank" rel="noreferrer">豆包开放平台</a></td></tr><tr><td>ChatGPT / Codex</td><td>本地 Codex 用 TOML。公开提交走 OpenAI 的插件审核流程，按平台当前规范准备 ZIP、MCP 配置和审核用例。 <a href="https://developers.openai.com/plugins/deploy/submission" target="_blank" rel="noreferrer">OpenAI 提交流程</a></td></tr><tr><td>Cursor</td><td>生成 MCP JSON。将插件清单和相关文件放入仓库，向 Cursor Marketplace 提交仓库地址。 <a href="https://cursor.com/marketplace/publish" target="_blank" rel="noreferrer">Cursor 提交入口</a></td></tr><tr><td>Claude</td><td>本地 Claude Desktop 示例用 stdio。提交远程连接器时，按 Connectors Directory 要求提供 HTTPS 服务、认证和测试材料。 <a href="https://claude.com/docs/connectors/building/submission" target="_blank" rel="noreferrer">Claude 目录提交</a></td></tr><tr><td>ZCode</td><td>生成嵌套的 <code>mcp.servers</code> 配置。官方市场接受包含 MCP 组件的插件，通过 GitHub PR 提交插件清单、市场条目和双语 README，再经维护者审核。 <a href="https://github.com/zai-org/zcode-plugins/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">ZCode 贡献指南</a></td></tr></tbody></table><h2 id="接入已经运行的-bot" tabindex="-1">接入已经运行的 Bot <a class="header-anchor" href="#接入已经运行的-bot" aria-label="Permalink to &quot;接入已经运行的 Bot&quot;">​</a></h2><ul><li><strong>直接接入 Bot Studio。</strong> 在支持单 Bot 发布的桌面版本中，选择 Bot、启动发布服务，并为调用方创建独立授权。HTTP MCP 连接器使用运行时给出的 <code>/mcp/&lt;publicationId&gt;</code> 地址。需要兼容 OpenAI 聊天客户端时，启用 <code>published.chat@1</code> 对应的接口，使用 <code>GET /v1/models</code> 和 <code>POST /v1/chat/completions</code>。桌面发布端点默认只监听本机，可先用于本地联调。 <a href="https://wave.sh.cn/openbot/bot-engine-runtime/" target="_blank" rel="noreferrer">BotEngine 对外发布说明</a></li><li><strong>接入自托管 Node。</strong> 从 <code>GET /api/v1/ping</code> 核对节点，按需启用外部集成。MCP 客户端使用单独入口发起任务，再使用交办返回的持久请求 ID 查询结果或取消。节点管理令牌应留在管理端。 <a href="/openbot/reference/node-api.html">Node API</a> · <a href="/openbot/guide/app-authorizations.html">自托管应用授权</a></li><li><strong>统一接入不同 Bot 后端。</strong> AnyBot-Connector 的 <code>anybot.connector/0.1</code> 定义调用者身份、授权、任务提交、查询、取消和回执，并提供 HTTP、MCP 与 Chat Completions 文本子集绑定。公开源码是可运行的参考 alpha，已验证隔离 TeamBot 后端。 <a href="https://github.com/Harzva/anybot-connector/blob/main/spec/0001-connector-contract.md" target="_blank" rel="noreferrer">连接器契约</a> · <a href="https://github.com/Harzva/anybot-connector/blob/main/spec/0002-alpha-api.md" target="_blank" rel="noreferrer">Alpha API</a> · <a href="https://github.com/Harzva/anybot-connector/blob/main/spec/0003-bindings.md" target="_blank" rel="noreferrer">绑定规范</a></li><li><strong>分发 Bot 角色模板。</strong> Awesome Bot 已公开 Bot 卡片、Agent 发现索引和可下载的 Fleet 模板。开发者可以读取 <code>awesome.bot.agent-discovery/1</code> 和 <code>awesome.bot.agent/1</code> 获取角色及导入配置。 <a href="https://github.com/Harzva/awesome-bot/blob/main/docs/agent-integration.md" target="_blank" rel="noreferrer">Awesome Bot 格式说明</a> · <a href="https://harzva.github.io/awesome-bot/" target="_blank" rel="noreferrer">市场页面</a></li><li><strong>在 Bot Studio 内导入 Codex 工作台。</strong> 本地工作台市场使用 <code>openbot.codex-workbench-market/1</code> 和 <code>openbot.codex-workbench-plugin/1</code>，DSH 插件通过 DSH2Codex 转译。相关工作台包已经在桌面版集成，目前为本地分发。 <a href="/openbot/development/architecture-report.html">技术架构</a></li></ul>`,11)])])}const g=t(i,[["render",o]]);export{k as __pageData,g as default};
